using System.Globalization;

public static class Solution
{
    public static string Initials(string fullName)
    {
        string[] names = fullName.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        var sb = new StringBuilder();
        foreach (string name in names) sb.Append(char.ToUpper(name[0])).Append('.');
        return sb.ToString();
    }

    public static string Slug(string title)
    {
        var sb = new StringBuilder();
        bool pendingDash = false;
        foreach (char c in title.ToLower())
        {
            if (char.IsLetterOrDigit(c))
            {
                if (pendingDash && sb.Length > 0) sb.Append('-');
                sb.Append(c);
                pendingDash = false;
            }
            else
            {
                pendingDash = true;
            }
        }
        return sb.ToString();
    }

    public static string PriceLine(string item, decimal price)
    {
        string amount = price.ToString("F2", CultureInfo.InvariantCulture);
        return $"{item,-12}{amount,8}";
    }

    public static int CountVowels(string text)
    {
        int count = 0;
        foreach (char c in text.ToLower())
        {
            if ("aeiou".Contains(c)) count++;
        }
        return count;
    }
}

