Test("initials", () =>
{
    CheckEq(Initials("ada king lovelace"), "A.K.L.");
    CheckEq(Initials("  Grace   Hopper "), "G.H.");
    CheckEq(Initials(""), "");
});

Test("slugs", () =>
{
    CheckEq(Slug("  Hello, World! C# 13 "), "hello-world-c-13");
    CheckEq(Slug("Already-a-slug"), "already-a-slug");
    CheckEq(Slug("!!!"), "");
    CheckEq(Slug("Tea & Cake"), "tea-cake");
});

Test("price lines", () =>
{
    CheckEq(PriceLine("Tea", 2.5m), "Tea             2.50");
    CheckEq(PriceLine("Chocolate cake", 12.345m), "Chocolate cake   12.35");
    CheckEq(PriceLine("Pen", 1234.5m).Length, 20);
});

Test("vowels", () =>
{
    CheckEq(CountVowels("Education"), 5);
    CheckEq(CountVowels("rhythm"), 0);
    CheckEq(CountVowels("AEIOU aeiou"), 10);
});

